from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(' ', '')
    groups = []
    stack = []
    current_group = ''
    for char in paren_string:
        if char == '(':
            if current_group:
                groups.append(current_group)
                current_group = ''
            stack.append(char)
        elif char == ')':
            if stack and stack[-1] == '(':
                stack.pop()
                current_group += char
                if not stack:
                    groups.append(current_group)
                    current_group = ''
    return groups
