def strange_sort_list(lst):
    sorted_lst = []
    while lst:
        min_val = min(lst)
        max_val = max(lst)
        if min_val != max_val:
            sorted_lst.extend([min_val, max_val])
        else:
            sorted_lst.append(min_val)
        lst.remove(min_val)
        if lst:
            lst.remove(max_val)
    return sorted_lst
