        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    count = 0
    for i in range(2, int(a ** 0.5) + 1):
        if a % i == 0 and is_prime(i):
            count += 1
            if count > 3:
                return False
            a //= i
            if a == 1:
                return True
    return count == 2 and is_prime(a)
