def is_multiply_prime(a):
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Initialize a counter for prime factors
    prime_factors_count = 0

    # Check divisibility by 2
    while a % 2 == 0:
        prime_factors_count += 1
        a //= 2

    # Check divisibility by odd numbers from 3 to sqrt(a)
    for i in range(3, int(a**0.5) + 1, 2):
        while a % i == 0:
            if is_prime(i):
                prime_factors_count += 1
            a //= i

    # If a is still greater than 2, it means a is a prime number itself
    if a > 2:
        if is_prime(a):
            prime_factors_count += 1

    # A number is a product of exactly 3 primes if it has exactly 3 prime factors
    return prime_factors_count == 3
```

