            return 'C'
        elif c.lower() == 'e':
            return 'G'
        elif c.lower() == 'i':
            return 'K'
        elif c.lower() == 'o':
            return 'Q'
        elif c.lower() == 'u':
            return 'W'
        else:
            return c

