def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    def swap_case(char):
        if char.islower():
            return char.upper()
        elif char.isupper():
            return char.lower()
        else:
            return char

    def replace_vowel(char):
        vowels = "aeiouAEIOU"
        if char in vowels:
            index = vowels.index(char)
            new_char = vowels[(index + 2) % len(vowels)]
            return new_char
        else:
            return char

    encoded_message = ""
    for char in message:
        encoded_message += swap_case(replace_vowel(char))

    return encoded_message
```

