def match_parens(lst):
    open_counter = 0
    close_counter = 0
    for s in lst:
        for c in s:
            if c == '(':
                open_counter += 1
            else:
                close_counter += 1
    if open_counter == close_counter:
        return 'Yes'
    else:
        return 'No'
