def match_parens(lst):
    open_bracket = lst[0].count('(')
    close_bracket = lst[0].count(')')
    if open_bracket >= close_bracket:
        close_bracket += lst[1].count('(')
        open_bracket -= lst[1].count(')')
        if open_bracket == close_bracket:
            return 'Yes'
    else:
        close_bracket += lst[1].count('(')
        open_bracket -= lst[1].count(')')
        if open_bracket == close_bracket:
            return 'Yes'

    return 'No'
```

