import heapq

def maximum(arr, k):
    if not arr or k == 0:
        return []
    if k == len(arr):
        return sorted(arr, reverse=True)

    heap = []
    for i in arr:
        heapq.heappush(heap, i)
        if len(heap) > k:
            heapq.heappop(heap)

    return sorted(heap, reverse=True)
