from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)

    def neighbors(x: int, y: int) -> List[tuple]:
        return [(x + dx, y + dy) for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)] if 0 <= x + dx < N and 0 <= y + dy < N]

    @lru_cache(None)
    def dp(x: int, y: int, k: int) -> List[int]:
        if k == 0:
            return [grid[x][y]]
        ans = []
        for nx, ny in neighbors(x, y):
            ans += dp(nx, ny, k - 1)
        return sorted(ans + [grid[x][y]])

    return dp(*[(i, j) for i in range(N) for j in range(N)][k - 1])
```

