def minPath(grid, k):
    import heapq

    n = len(grid)
    heap = []
    for i in range(n):
        for j in range(n):
            heapq.heappush(heap, (grid[i][j], i, j))

    visited = [[False] * n for _ in range(n)]

    while heap:
        val, x, y = heapq.heappop(heap)
        if visited[x][y]:
            continue

        visited[x][y] = True
        if k == 0:
            return [val]

        paths = []
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                paths.append((val, nx, ny))
        paths.sort()

        for val, nx, ny in paths:
            path = minPath(grid, k - 1)
            path.append(val)
            yield path
