def get_max_triples(n):
    count = 0
    for i in range(1, n + 1):
        a_i = i * i - i + 1

        for j in range(i + 1, n + 1):
            a_j = j * j - j + 1

            for k in range(j + 1, n + 1):
                a_k = k * k - k + 1

                if (a_i + a_j + a_k) % 3 == 0:
                    count += 1

    return count
