def solve(s):
    """You are given a string s.
    if s[i] is a letter, reverse its case from lower to upper or vise versa, 
    otherwise keep it as it is.
    If the string contains no letters, reverse the string.
    The function should return the resulted string.
    Examples
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    letters = [char.lower() for char in s if char.isalpha()]
    non_letters = [char.upper() if char.islower() else char.lower() for char in s if not char.isalpha()]

    if len(letters) == 0:
        return ''.join(reversed(non_letters))
    else:
        return ''.join([letters[i] if not char.isalpha() else non_letters[i] for i, char in enumerate(s)])
```

